customCSS:
.t, .history { color: #75715e; }
.join { color: #a6e22e; }
.part, .quit { color: #75715e; }
.kick, .error { color: #f92672; }
.notice { color: #e6db74; }
.action { color: #ae81ff; }
.mode, .nick, .topic, .server { color: #66d9ef; }
.highlight { color: #f8f8f2; background-color: #49483e; border-left: 3px solid #ae81ff; padding-left: 8px; }
.reply { color: #75715e; border-left: 2px solid #66d9ef; padding-left: 6px; }
.oper { color: #272822; background-color: #e6db74; }
.reactions { color: #66d9ef; background-color: #3e3d32; }
.card { background-color: #3e3d32; border-color: #75715e; }
.card-title { color: #66d9ef; }
.card-desc { color: #75715e; }
.daychange { color: #75715e; border-color: #3e3d32; }
